<script setup lang="ts">
import { provide, ref } from 'vue'
import Icon from '../../src/components/visual/ArchiveIcon.vue'
import Materials from './MaterialsPanel.vue'
import Inspector from './InspectorPanel.vue'
import Popover from '../../src/components/ui/StudioPopover.vue'
import { previewKey, usePreview } from './usePreview'
const p = usePreview()
provide(previewKey, p)
const previewDialog = ref<HTMLDialogElement>()
const toolsOpen = ref(false)
function openImage() { previewDialog.value?.showModal() }
const navigation = [{name:'首页',path:'/',icon:'image'},{name:'绘制',path:'/prompt-builder',icon:'spark'},{name:'角色',path:'/character',icon:'character'},{name:'灵感',path:'/scene-explorer',icon:'scene'},{name:'参考画册',path:'/showcase',icon:'gallery'},{name:'我的作品',path:'/gallery',icon:'gallery'},{name:'房间',path:'/chat',icon:'chat'}] as const
</script>
<template>
  <div class="reference" :style="{'--preview-material-width':p.s.materialWidth+'px','--preview-inspector-width':p.s.inspectorWidth+'px'}" :class="{'focus-mode':p.s.focused,'without-materials':!p.materialsOpen,'without-inspector':!p.s.inspectorVisible}">
    <a class="skip-link" href="#canvas">跳到画布</a>
    <div class="prototype-ribbon"><span><b>设计参考 01</b><span class="ribbon-detail">独立交互原型 · 状态模拟 · 不调用模型</span></span><div class="preview-states" role="group" aria-label="预览状态"><button v-for="state in [{id:'normal',label:'正常创作'},{id:'generating',label:'生成中'},{id:'advanced',label:'参数展开'},{id:'error',label:'错误'}]" :key="state.id" :aria-pressed="p.s.scenario===state.id" @click="p.setScenario(state.id)">{{state.label}}</button></div></div>
    <header class="global-header"><a class="brand" href="/" target="_blank" aria-label="绘遇首页（正式页面，新窗口）"><img :src="p.s.theme==='light' ? '/assets/logo-light.svg' : '/assets/logo.svg'" alt="绘遇 HUIYU" /></a><span class="header-divider"></span><nav aria-label="主导航"><a v-for="nav in navigation" :key="nav.name" :href="nav.path" target="_blank" :aria-current="nav.name==='绘制' ? 'page' : undefined"><Icon :name="nav.icon" />{{nav.name}}</a></nav><div class="header-actions"><button class="icon-button" aria-label="搜索页面、场景与作品（预览）" @click="p.notify('全局搜索入口保留；本原型不检索实际作品。左侧场景分类支持预览范围内搜索。')"><Icon name="search" /></button><button class="subtle-button" @click="p.s.inspector='tasks';p.s.inspectorVisible=true"><Icon name="queue" />任务<span v-if="p.busy" class="count">1</span></button><button class="icon-button" :aria-label="p.s.theme==='light' ? '切换为深色模式' : '切换为浅色模式'" @click="p.setTheme()"><Icon :name="p.s.theme==='light' ? 'moon' : 'sun'" /></button><Popover v-model:open="toolsOpen" label="更多工具" content-class="preview-menu"><template #trigger><button class="icon-button" aria-label="更多工具"><Icon name="menu" /></button></template><strong>创作工具</strong><button v-for="label in ['夏目的灵感骰子','夏目的调色笔记','数据工具 · 导入与备份']" :key="label" @click="toolsOpen=false;p.notify(label+'：保留正式入口语义，此原型不改写资料。')">{{label}}<Icon name="chevron-down" /></button><a href="/style" target="_blank">画风</a><a href="/lora" target="_blank">模型资料</a><a href="/control" target="_blank">控制面板</a><small>链接打开正式页面；创作动作仅模拟。</small></Popover></div></header>
    <div class="workspace-heading"><div><div class="heading-line"><h1>绘图画室</h1><span class="connection" :class="{'is-offline':p.s.compare}"><span></span>{{p.s.render.family==='anima' ? 'Anima' : 'Krea 2'}} <b>{{p.s.compare ? '未连接' : '模拟连接'}}</b></span></div><p>让想象成形，让故事相遇。</p></div><div class="workspace-actions"><div class="segmented mode-switch" role="group" aria-label="创作模式"><button :aria-pressed="!p.s.expert" @click="p.s.expert=false">场景模式</button><button :aria-pressed="p.s.expert" @click="p.s.expert=true">专家模式</button></div><button class="subtle-button" id="materials-toggle" :aria-pressed="p.materialsOpen" @click="p.toggleMaterials()"><Icon name="manager" />素材</button><button class="subtle-button" :aria-pressed="p.s.inspectorVisible" @click="p.s.inspectorVisible=!p.s.inspectorVisible"><Icon name="gear" />参数</button><button class="subtle-button" :aria-pressed="p.s.focused" @click="p.s.focused=!p.s.focused"><Icon :name="p.s.focused ? 'compress' : 'expand'" />{{p.s.focused ? '退出专注' : '专注成片'}}</button></div></div>
    <main class="workspace"><template v-if="!p.s.narrow && !p.s.focused"><div v-if="p.materialsOpen" class="resize-handle material-handle" role="separator" aria-label="调整素材栏宽度" aria-orientation="vertical" :aria-valuenow="p.s.materialWidth" :aria-valuemin="280" :aria-valuemax="480" tabindex="0" @pointerdown="p.startResize('materialWidth',$event)" @pointermove="p.moveResize" @pointerup="p.endResize" @pointercancel="p.endResize" @keydown="p.keyResize('materialWidth',$event)"></div><div v-if="p.s.inspectorVisible" class="resize-handle inspector-handle" role="separator" aria-label="调整参数栏宽度" aria-orientation="vertical" :aria-valuenow="p.s.inspectorWidth" :aria-valuemin="280" :aria-valuemax="480" tabindex="0" @pointerdown="p.startResize('inspectorWidth',$event)" @pointermove="p.moveResize" @pointerup="p.endResize" @pointercancel="p.endResize" @keydown="p.keyResize('inspectorWidth',$event)"></div></template>
