        <div class="canvas-heading"><div><Icon name="image" /><strong>{{p.s.hasImage ? (p.s.sourceImage==='landscape' ? '夏目 · 雨夜咖啡馆' : '夏目 · 暖光教室') : p.scene.title}}</strong><span class="canvas-source">{{p.s.hasImage ? '现有品牌素材' : '场景参考'}}</span></div><button class="text-button" @click="p.s.sourceImage=p.s.sourceImage==='portrait' ? 'landscape' : 'portrait';p.s.hasImage=true"><Icon name="image" />{{p.s.sourceImage==='portrait' ? '查看横幅素材' : '查看竖幅素材'}}</button></div>
