        <div class="artwork-toolbar" role="group" aria-label="作品操作"><div><button :disabled="p.busy || !p.s.hasImage" @click="p.s.archived=!p.s.archived;p.notify(p.s.archived ? '模拟：已存入作品册。未创建或修改真实记录。' : '模拟：已取消入册状态。')"><Icon :name="p.s.archived ? 'success' : 'gallery'" />{{p.s.archived ? '已入册（模拟）' : '存入作品册'}}</button><button :disabled="p.busy || !p.s.hasImage" @click="p.notify('保存为场景仅演示入口，未写入内容工作库。')"><Icon name="scene" />保存为场景</button><button disabled aria-describedby="compare-reason"><Icon name="compare" />与上一张对比</button></div><button class="text-button" :disabled="p.busy || !p.s.hasImage" @click="p.s.hasImage=false;p.notify('已清除预览画布。原素材未被修改。')"><Icon name="close" />清除图片</button></div>
        <div class="canvas-footer"><p id="compare-reason">{{p.busy ? '生成时保留参考与构图，操作位置保持稳定。' : '场景参考用于观察氛围；没有上一张成片，对比暂不可用。'}}</p><a href="/gallery" target="_blank">我的作品<Icon name="expand" /></a></div>
        <div v-if="!p.s.inspectorVisible || p.s.focused" class="compact-dock"><span>{{p.s.ratio.replace('x',' × ')}} · {{p.s.render.steps}} 步</span><button class="generate-button" :disabled="p.s.compare" @click="p.generate()"><Icon name="spark" />{{p.busy ? '停止绘制' : '生成图片'}}<small>模拟</small></button></div>
      </section>
      <Inspector v-if="p.s.inspectorVisible && !p.s.focused" />
