    <div v-if="p.s.message" class="preview-notice" role="status"><Icon name="info" /><span>{{p.s.message}}</span><button class="icon-button" aria-label="关闭提示" @click="p.s.message=''"><Icon name="close" /></button></div>
    <dialog ref="previewDialog" class="image-dialog" @click="($event.target===previewDialog) && previewDialog?.close()"><form method="dialog"><strong>原始参考 · 非本次生成</strong><button class="icon-button" aria-label="关闭图片预览" autofocus><Icon name="close" /></button></form><img :src="p.picture" alt="完整参考图片" /></dialog>
  </div>
</template>
